INSERT INTO breath_manager_v5.bm5_retrieval_preview (retrieval_id, entry_type, entry_id, title, category_id, answer_preview, source_passage_ids, answer_constraints, safety_ids, related_entry_ids, production_ready, preview_allowed) VALUES (NULL, 'knowledge', 'K007', 'ミトコンドリアの役割', 'cell_energy', NULL, ARRAY['P07','P044','P167','P168','P170']::text[], '[{"issue_id":"I003","rule":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。"},{"issue_id":"I004","rule":"多くの細胞では、ミトコンドリアがATPの産生に関わります。"},{"issue_id":"I005","rule":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。"},{"issue_id":"I021","rule":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。"},{"issue_id":"I038","rule":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。"}]'::jsonb, '{}', '{}', false, false) ON CONFLICT (retrieval_id) DO NOTHING;
